from typing import Protocol


class ICacheStorage(Protocol):
    """Интерфейс бэкенда хранилища."""

    async def get(self, key: str) -> str | None: ...
    async def set(
        self,
        key: str,
        value: str,
        ttl: int,
        user_id: int | None = None,
    ) -> None: ...
    async def delete(self, key: str) -> bool: ...
    async def get_all(self, user_id: int) -> dict: ...
    async def clear_user_session(self, user_id: int) -> bool: ...
    async def set_user_state(self, user_id: int, state: str): ...
